<?php
require_once __DIR__.'/../config.php';require_admin();
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$st=$conn->prepare("DELETE FROM products WHERE id=?");$st->bind_param("i",$id);$st->execute();$_SESSION['flash']=['type'=>'success','message'=>'Produk dihapus.'];redirect('products.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$cat=(int)($_POST['category_id']??0);$status=$_POST['status']==='inactive'?'inactive':'active';$image=$_POST['old_image']??'';
 if(!empty($_FILES['image']['name'])){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'])){$error='Format gambar harus JPG, PNG, atau WEBP.';}else{$image=uniqid('produk_',true).'.'.$ext;if(!move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/../uploads/'.$image))$error='Gagal mengunggah gambar.';}}
 if(empty($error)&&$name!==''&&$price>=0&&$stock>=0){
  if($id){$st=$conn->prepare("UPDATE products SET category_id=?,name=?,description=?,price=?,stock=?,image=?,status=? WHERE id=?");$st->bind_param("issdissi",$cat,$name,$desc,$price,$stock,$image,$status,$id);}
  else{$st=$conn->prepare("INSERT INTO products(category_id,name,description,price,stock,image,status) VALUES(?,?,?,?,?,?,?)");$st->bind_param("issdiss",$cat,$name,$desc,$price,$stock,$image,$status);}
  if($st->execute()){$_SESSION['flash']=['type'=>'success','message'=>'Data produk berhasil disimpan.'];redirect('products.php');}else{$error='Gagal menyimpan produk.';}
 }elseif(empty($error))$error='Nama produk wajib diisi.';
}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$st=$conn->prepare("SELECT * FROM products WHERE id=?");$st->bind_param("i",$id);$st->execute();$edit=$st->get_result()->fetch_assoc();}
$cats=$conn->query("SELECT * FROM categories ORDER BY name");$rows=$conn->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC");include '_header.php';?>
<h1 class="h3 fw-bold mb-4">Kelola Produk</h1><div class="card border-0 shadow-sm p-4 mb-4"><h5><?=$edit?'Edit':'Tambah'?> Produk</h5><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><input type="hidden" name="old_image" value="<?=e($edit['image']??'')?>"><div class="col-md-6"><label class="form-label">Nama produk</label><input class="form-control" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="col-md-6"><label class="form-label">Kategori</label><select class="form-select" name="category_id"><option value="0">Tanpa kategori</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endwhile;?></select></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea class="form-control" name="description" rows="2"><?=e($edit['description']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Harga</label><input type="number" min="0" step="100" class="form-control" name="price" required value="<?=e($edit['price']??0)?>"></div><div class="col-md-4"><label class="form-label">Stok</label><input type="number" min="0" class="form-control" name="stock" required value="<?=e($edit['stock']??0)?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active">Aktif</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Nonaktif</option></select></div><div class="col-md-8"><label class="form-label">Foto produk</label><input type="file" class="form-control" name="image" accept=".jpg,.jpeg,.png,.webp"></div><div class="col-12"><button class="btn btn-success">Simpan Produk</button> <a href="products.php" class="btn btn-light">Reset</a></div></form></div>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><?=e($r['category_name']??'-')?></td><td><?=rupiah($r['price'])?></td><td><?=$r['stock']?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus produk ini?')" href="?delete=<?=$r['id']?>">Hapus</a></td></tr><?php endwhile;?></tbody></table></div></div><?php include '_footer.php';?>